import{ax as e,A as l,aQ as i,z as t}from"./chunks/framework.BWRXlwpK.js";const m=JSON.parse('{"title":"React","description":"","frontmatter":{},"headers":[],"relativePath":"qa/react.md","filePath":"qa/react.md","lastUpdated":1788144986000}'),r={name:"qa/react.md"};function o(c,a,u,n,h,s){return t(),l("div",null,a[0]||(a[0]=[i('<h1 id="react" tabindex="-1">React <a class="header-anchor" href="#react" aria-label="Permalink to &quot;React&quot;">​</a></h1><h2 id="react-和-vue-有什么区别" tabindex="-1">React 和 Vue 有什么区别？ <a class="header-anchor" href="#react-和-vue-有什么区别" aria-label="Permalink to &quot;React 和 Vue 有什么区别？&quot;">​</a></h2><ul><li>模板 vs JSX：Vue 使用模板语法，React 使用 JSX，逻辑和视图都在 JS 里</li><li>更新机制：Vue 基于响应式系统自动追踪依赖，细粒度更新；React 需要 setState 主动触发，配合 memo/useMemo 做优化</li><li>数据流：两者都是单向数据流，Vue 还有 v-model 等语法糖</li><li>生态：Vue 上手快、官方配套全；React 生态更灵活庞大，更偏函数式</li><li>学习曲线：Vue 平缓，React 需要理解 JSX、Hooks、渲染机制等</li></ul><h2 id="react-为什么使用-jsx" tabindex="-1">React 为什么使用 JSX？ <a class="header-anchor" href="#react-为什么使用-jsx" aria-label="Permalink to &quot;React 为什么使用 JSX？&quot;">​</a></h2><ul><li>声明式描述 UI，结构直观，接近 HTML</li><li>与 JS 无缝结合，逻辑和视图写在一起，方便表达条件、循环</li><li>最终由 Babel 编译成 React.createElement() 调用</li></ul><h2 id="jsx-是什么" tabindex="-1">JSX 是什么？ <a class="header-anchor" href="#jsx-是什么" aria-label="Permalink to &quot;JSX 是什么？&quot;">​</a></h2><ul><li>JSX 是 JavaScript 的语法扩展，可以在 JS 里写类似 HTML 的结构</li><li>它不是模板引擎，编译后就是普通的 JS 函数调用</li></ul><h2 id="jsx-中为什么只能有一个根节点" tabindex="-1">JSX 中为什么只能有一个根节点？ <a class="header-anchor" href="#jsx-中为什么只能有一个根节点" aria-label="Permalink to &quot;JSX 中为什么只能有一个根节点？&quot;">​</a></h2><ul><li>因为 JSX 最终编译成 React.createElement() 调用，一个函数只能返回一个值</li><li>需要多个节点时用 Fragment（<code>&lt;&gt;&lt;/&gt;</code>）包裹，它不会产生额外 DOM</li></ul><h2 id="jsx-中-class-为什么写成-classname" tabindex="-1">JSX 中 class 为什么写成 className？ <a class="header-anchor" href="#jsx-中-class-为什么写成-classname" aria-label="Permalink to &quot;JSX 中 class 为什么写成 className？&quot;">​</a></h2><ul><li>因为 class 是 JavaScript 的保留字，JSX 本质是 JS，不能直接用</li><li>同理，for 要写成 htmlFor</li></ul><h2 id="jsx-中如何绑定事件" tabindex="-1">JSX 中如何绑定事件？ <a class="header-anchor" href="#jsx-中如何绑定事件" aria-label="Permalink to &quot;JSX 中如何绑定事件？&quot;">​</a></h2><ul><li>用驼峰命名 + 函数引用，如 <code>onClick={handleClick}</code></li><li>不是字符串，而是传函数，需要传参时用箭头函数包一层</li></ul><h2 id="react-中事件和原生-dom-事件有什么区别" tabindex="-1">React 中事件和原生 DOM 事件有什么区别？ <a class="header-anchor" href="#react-中事件和原生-dom-事件有什么区别" aria-label="Permalink to &quot;React 中事件和原生 DOM 事件有什么区别？&quot;">​</a></h2><ul><li>React 事件是合成事件（SyntheticEvent），统一了浏览器差异</li><li>通过事件委托绑定到根容器上（React 17+ 挂在 root 上），不是直接绑在元素上</li><li>命名是驼峰（onClick），原生是小写（onclick）</li><li>合成事件对象是池化的，异步访问属性需要注意</li></ul><h2 id="react-为什么需要-key" tabindex="-1">React 为什么需要 key？ <a class="header-anchor" href="#react-为什么需要-key" aria-label="Permalink to &quot;React 为什么需要 key？&quot;">​</a></h2><ul><li>帮助 React 在 diff 时识别列表中的每个节点，判断复用、更新还是删除</li><li>没有 key 时列表重排只能靠顺序对比，效率低且容易渲染错乱</li></ul><h2 id="key-为什么不能使用-index" tabindex="-1">key 为什么不能使用 index？ <a class="header-anchor" href="#key-为什么不能使用-index" aria-label="Permalink to &quot;key 为什么不能使用 index？&quot;">​</a></h2><ul><li>列表插入、删除、排序后 index 会变，React 会复用错误的节点</li><li>导致组件状态错乱、DOM 复用错误，比如输入框内容串位</li><li>应该使用稳定且唯一的 id</li></ul><h2 id="什么是受控组件" tabindex="-1">什么是受控组件？ <a class="header-anchor" href="#什么是受控组件" aria-label="Permalink to &quot;什么是受控组件？&quot;">​</a></h2><ul><li>表单元素的 value 由 React state 控制，通过 onChange 更新 state</li><li>数据单向流入，值始终和 state 一致，便于校验和处理</li></ul><h2 id="什么是非受控组件" tabindex="-1">什么是非受控组件？ <a class="header-anchor" href="#什么是非受控组件" aria-label="Permalink to &quot;什么是非受控组件？&quot;">​</a></h2><ul><li>表单值由 DOM 自己维护，需要时通过 ref 获取</li><li>代码简单，但值不在 React 掌控中，需要主动读取</li></ul><h2 id="react-中如何获取-dom" tabindex="-1">React 中如何获取 DOM？ <a class="header-anchor" href="#react-中如何获取-dom" aria-label="Permalink to &quot;React 中如何获取 DOM？&quot;">​</a></h2><ul><li>函数组件用 useRef：<code>const inputRef = useRef(null)</code>，<code>&lt;input ref={inputRef} /&gt;</code></li><li>类组件用 React.createRef()</li><li>给子组件传 ref 需要 forwardRef 包裹，配合 useImperativeHandle 暴露方法</li></ul><h2 id="函数组件和类组件有什么区别" tabindex="-1">函数组件和类组件有什么区别？ <a class="header-anchor" href="#函数组件和类组件有什么区别" aria-label="Permalink to &quot;函数组件和类组件有什么区别？&quot;">​</a></h2><ul><li>类组件有 this、生命周期、state，写法冗长</li><li>函数组件更简洁，配合 Hooks 同样能管理 state 和副作用</li><li>React 官方推荐函数组件 + Hooks</li></ul><h2 id="什么是-virtual-dom" tabindex="-1">什么是 Virtual DOM？ <a class="header-anchor" href="#什么是-virtual-dom" aria-label="Permalink to &quot;什么是 Virtual DOM？&quot;">​</a></h2><ul><li>用 JS 对象模拟真实 DOM 结构，描述 UI 状态</li><li>更新时先在 Virtual DOM 上做 diff，算出最小变更，再批量更新真实 DOM</li></ul><h2 id="react-为什么需要-virtual-dom" tabindex="-1">React 为什么需要 Virtual DOM？ <a class="header-anchor" href="#react-为什么需要-virtual-dom" aria-label="Permalink to &quot;React 为什么需要 Virtual DOM？&quot;">​</a></h2><ul><li>直接频繁操作真实 DOM 会触发大量重排重绘，性能差</li><li>Virtual DOM 通过 diff 减少真实 DOM 操作次数，提高渲染性能</li><li>不依赖浏览器，可以跨平台（React Native）</li><li>让开发者声明式编程，不用关心 DOM 细节</li></ul><h2 id="react-的-virtual-dom-和-vue-的-virtual-dom-有什么区别" tabindex="-1">React 的 Virtual DOM 和 Vue 的 Virtual DOM 有什么区别？ <a class="header-anchor" href="#react-的-virtual-dom-和-vue-的-virtual-dom-有什么区别" aria-label="Permalink to &quot;React 的 Virtual DOM 和 Vue 的 Virtual DOM 有什么区别？&quot;">​</a></h2><ul><li>Vue 的模板是编译时的，可以做静态分析优化（静态节点提升、PatchFlags 标记）</li><li>React 的 JSX 偏运行时，diff 时需要更完整地对比</li><li>Vue 的 diff 有双端对比优化，React 的 Fiber 支持可中断渲染和优先级调度</li></ul><h2 id="react-是如何进行-diff-的" tabindex="-1">React 是如何进行 Diff 的？ <a class="header-anchor" href="#react-是如何进行-diff-的" aria-label="Permalink to &quot;React 是如何进行 Diff 的？&quot;">​</a></h2><ul><li>同层对比：只比较同一层的节点，不跨层移动</li><li>类型不同直接替换整棵子树</li><li>类型相同则复用 DOM，只更新属性</li><li>列表通过 key 识别复用节点</li></ul><h2 id="react-为什么不能直接操作-dom" tabindex="-1">React 为什么不能直接操作 DOM？ <a class="header-anchor" href="#react-为什么不能直接操作-dom" aria-label="Permalink to &quot;React 为什么不能直接操作 DOM？&quot;">​</a></h2><ul><li>直接操作会破坏 React 对 DOM 的掌控，导致虚拟 DOM 和真实 DOM 状态不一致</li><li>React 是声明式框架，期望开发者只描述 UI，由 React 负责更新</li><li>破坏 React 的优化机制（复用、批量更新等）</li></ul><h2 id="react-的-fiber-是什么" tabindex="-1">React 的 Fiber 是什么？ <a class="header-anchor" href="#react-的-fiber-是什么" aria-label="Permalink to &quot;React 的 Fiber 是什么？&quot;">​</a></h2><ul><li>React 16 引入的新的协调引擎，核心是&quot;可中断的渲染&quot;</li><li>把渲染拆成一个个 fiber 任务单元，支持暂停、恢复、按优先级调度</li><li>解决旧版递归渲染阻塞主线程的问题，配合时间切片让出主线程，保证交互流畅</li></ul><h2 id="react-的-render-阶段和-commit-阶段是什么" tabindex="-1">React 的 Render 阶段和 Commit 阶段是什么？ <a class="header-anchor" href="#react-的-render-阶段和-commit-阶段是什么" aria-label="Permalink to &quot;React 的 Render 阶段和 Commit 阶段是什么？&quot;">​</a></h2><ul><li>Render 阶段：调用组件函数、构建/更新 Fiber 树，计算变化，这个阶段可以中断</li><li>Commit 阶段：把变化提交到真实 DOM，执行副作用（useEffect、生命周期），不可中断</li><li>对应 current 树和 workInProgress 树双缓冲机制</li></ul><h2 id="props-是什么" tabindex="-1">Props 是什么？ <a class="header-anchor" href="#props-是什么" aria-label="Permalink to &quot;Props 是什么？&quot;">​</a></h2><ul><li>父组件传给子组件的参数，用于配置子组件</li><li>只读，形成单向数据流</li></ul><h2 id="state-是什么" tabindex="-1">State 是什么？ <a class="header-anchor" href="#state-是什么" aria-label="Permalink to &quot;State 是什么？&quot;">​</a></h2><ul><li>组件内部管理的状态，通过 setState 更新</li><li>state 变化会触发组件重新渲染</li></ul><h2 id="props-和-state-有什么区别" tabindex="-1">Props 和 State 有什么区别？ <a class="header-anchor" href="#props-和-state-有什么区别" aria-label="Permalink to &quot;Props 和 State 有什么区别？&quot;">​</a></h2><ul><li>props 是外部传入的，state 是组件自己维护的</li><li>props 只读不能改，state 通过 setState 修改</li><li>两者变化都会触发重新渲染</li></ul><h2 id="props-可以修改吗" tabindex="-1">Props 可以修改吗？ <a class="header-anchor" href="#props-可以修改吗" aria-label="Permalink to &quot;Props 可以修改吗？&quot;">​</a></h2><ul><li>不可以，props 是只读的</li><li>子组件需要修改时，应该调用父组件传入的回调，由父组件修改，或把状态提升</li></ul><h2 id="state-为什么不能直接修改" tabindex="-1">State 为什么不能直接修改？ <a class="header-anchor" href="#state-为什么不能直接修改" aria-label="Permalink to &quot;State 为什么不能直接修改？&quot;">​</a></h2><ul><li>直接修改不会触发重新渲染，React 感知不到变化</li><li>setState 会触发渲染调度，并且是不可变更新，方便 diff 对比和调试</li></ul><h2 id="什么是-hooks" tabindex="-1">什么是 Hooks？ <a class="header-anchor" href="#什么是-hooks" aria-label="Permalink to &quot;什么是 Hooks？&quot;">​</a></h2><ul><li>React 16.8 引入的一组函数，让函数组件也能使用 state、生命周期等能力</li><li>常用：useState、useEffect、useRef、useMemo、useCallback、useContext、useReducer</li></ul><h2 id="为什么-react-要引入-hooks" tabindex="-1">为什么 React 要引入 Hooks？ <a class="header-anchor" href="#为什么-react-要引入-hooks" aria-label="Permalink to &quot;为什么 React 要引入 Hooks？&quot;">​</a></h2><ul><li>解决类组件逻辑复用难的问题（HOC、render props 容易嵌套地狱）</li><li>状态逻辑可以抽成自定义 Hook 复用</li><li>函数组件更简洁，没有 this 绑定问题</li><li>把相关副作用集中管理，替代零散的生命周期</li></ul><h2 id="组件通信" tabindex="-1">组件通信 <a class="header-anchor" href="#组件通信" aria-label="Permalink to &quot;组件通信&quot;">​</a></h2><ul><li>父传子：props</li><li>子传父：父组件传回调函数，子组件调用并传参</li><li>兄弟组件：状态提升到共同的父组件</li><li>跨层级：Context</li><li>全局状态：Redux、Zustand 等状态管理库</li><li>父组件调用子组件方法：forwardRef + useImperativeHandle</li></ul><h2 id="react-为什么会重新渲染" tabindex="-1">React 为什么会重新渲染？ <a class="header-anchor" href="#react-为什么会重新渲染" aria-label="Permalink to &quot;React 为什么会重新渲染？&quot;">​</a></h2><ul><li>setState 更新 state</li><li>父组件重新渲染，默认子组件跟着重新渲染</li><li>props 引用变化、context 值变化</li></ul><h2 id="什么情况下组件会重新渲染" tabindex="-1">什么情况下组件会重新渲染？ <a class="header-anchor" href="#什么情况下组件会重新渲染" aria-label="Permalink to &quot;什么情况下组件会重新渲染？&quot;">​</a></h2><ul><li>自身 state 变化</li><li>父组件传入的 props 变化</li><li>订阅的 context 变化</li><li>父组件重新渲染（未用 memo 时子组件默认跟随）</li></ul><h2 id="react-如何避免不必要的重新渲染" tabindex="-1">React 如何避免不必要的重新渲染？ <a class="header-anchor" href="#react-如何避免不必要的重新渲染" aria-label="Permalink to &quot;React 如何避免不必要的重新渲染？&quot;">​</a></h2><ul><li>React.memo 包裹组件，props 没变化时跳过渲染</li><li>useMemo 缓存计算结果，useCallback 缓存函数引用，保证 props 稳定</li><li>状态拆分下沉，避免一个大的 state 让整棵树都渲染</li><li>把频繁变化的部分隔离成独立组件</li></ul><h2 id="一个组件为什么会重新渲染" tabindex="-1">一个组件为什么会重新渲染？ <a class="header-anchor" href="#一个组件为什么会重新渲染" aria-label="Permalink to &quot;一个组件为什么会重新渲染？&quot;">​</a></h2><ul><li>本质就三类：state 变了、props 变了（引用变化）、context 变了</li><li>注意父组件渲染时，子组件默认也会渲染，除非用 memo 阻断</li></ul><h2 id="如何优化一个频繁重新渲染的组件" tabindex="-1">如何优化一个频繁重新渲染的组件？ <a class="header-anchor" href="#如何优化一个频繁重新渲染的组件" aria-label="Permalink to &quot;如何优化一个频繁重新渲染的组件？&quot;">​</a></h2><ul><li>React.memo 包裹 + useCallback/useMemo 稳定 props</li><li>拆分组件，让状态只影响需要的部分</li><li>大量数据用虚拟列表，只渲染可视区</li><li>合并多次 setState，减少渲染次数</li></ul><h2 id="一个页面有-10000-条数据-react-如何优化" tabindex="-1">一个页面有 10000 条数据，React 如何优化？ <a class="header-anchor" href="#一个页面有-10000-条数据-react-如何优化" aria-label="Permalink to &quot;一个页面有 10000 条数据，React 如何优化？&quot;">​</a></h2><ul><li>用虚拟列表（react-window / react-virtualized），只渲染可视区域</li><li>或分页、懒加载</li><li>每条数据是纯展示组件，用 React.memo 避免无关更新</li><li>不要一次性渲染大量 DOM</li></ul><h2 id="react-中如何实现权限路由" tabindex="-1">React 中如何实现权限路由？ <a class="header-anchor" href="#react-中如何实现权限路由" aria-label="Permalink to &quot;React 中如何实现权限路由？&quot;">​</a></h2><ul><li>封装一个路由守卫组件，根据路由配置里的 roles 和当前用户角色判断</li><li>有权限则渲染目标组件，无权限跳转 403 或登录页</li><li>配合路由配置遍历生成 Routes</li></ul><h2 id="react-中如何实现登录状态持久化" tabindex="-1">React 中如何实现登录状态持久化？ <a class="header-anchor" href="#react-中如何实现登录状态持久化" aria-label="Permalink to &quot;React 中如何实现登录状态持久化？&quot;">​</a></h2><ul><li>登录成功后把 token 存 localStorage / sessionStorage（或 cookie）</li><li>用户信息放在全局状态（Redux / Zustand）</li><li>应用启动时从 storage 恢复，请求拦截器统一带上 Authorization</li><li>刷新页面时根据 token 重新拉取用户信息</li></ul><h2 id="react-中如何实现-token-自动刷新" tabindex="-1">React 中如何实现 Token 自动刷新？ <a class="header-anchor" href="#react-中如何实现-token-自动刷新" aria-label="Permalink to &quot;React 中如何实现 Token 自动刷新？&quot;">​</a></h2><ul><li>请求拦截器遇到 401，用 refresh_token 调刷新接口</li><li>刷新成功拿到新 token，更新存储并重放原请求</li><li>用一个&quot;单例 Promise + 等待队列&quot;保证并发请求只刷新一次</li></ul><h2 id="react-中如何处理接口竞态问题" tabindex="-1">React 中如何处理接口竞态问题？ <a class="header-anchor" href="#react-中如何处理接口竞态问题" aria-label="Permalink to &quot;React 中如何处理接口竞态问题？&quot;">​</a></h2><ul><li>用 AbortController / axios cancelToken 取消过期请求</li><li>或者记录最新请求序号，响应返回时判断是否还是最新，不是就丢弃</li><li>组件卸载时清理，避免 setState 警告</li></ul><h2 id="react-中如何取消请求" tabindex="-1">React 中如何取消请求？ <a class="header-anchor" href="#react-中如何取消请求" aria-label="Permalink to &quot;React 中如何取消请求？&quot;">​</a></h2><ul><li>fetch 用 AbortController：<code>abortController.abort()</code></li><li>axios 用 AbortSignal 或 CancelToken</li><li>在 useEffect 的清理函数里调用 abort，组件卸载自动取消</li></ul><h2 id="react-中如何实现全局-loading" tabindex="-1">React 中如何实现全局 Loading？ <a class="header-anchor" href="#react-中如何实现全局-loading" aria-label="Permalink to &quot;React 中如何实现全局 Loading？&quot;">​</a></h2><ul><li>全局状态维护一个请求计数：发起 +1，结束 -1，为 0 时隐藏</li><li>在 axios 请求/响应拦截器里统一增减</li><li>或直接调用 antd 的 message/Spin 全局实例</li></ul><h2 id="react-中如何实现错误处理" tabindex="-1">React 中如何实现错误处理？ <a class="header-anchor" href="#react-中如何实现错误处理" aria-label="Permalink to &quot;React 中如何实现错误处理？&quot;">​</a></h2><ul><li>请求层：axios 拦截器统一处理错误码和提示</li><li>渲染层：Error Boundary 捕获渲染错误，展示降级 UI</li><li>全局：监听 unhandledrejection 兜底异步异常</li><li>上报：错误统一记录并上报监控平台</li></ul><h2 id="react-中如何实现-error-boundary" tabindex="-1">React 中如何实现 Error Boundary？ <a class="header-anchor" href="#react-中如何实现-error-boundary" aria-label="Permalink to &quot;React 中如何实现 Error Boundary？&quot;">​</a></h2><ul><li>类组件实现 getDerivedStateFromError 和 componentDidCatch</li><li>捕获子树渲染错误，渲染备用 UI 并上报</li><li>注意：只能捕获渲染期和生命周期错误，事件处理、异步错误捕获不到，需要配合全局兜底</li></ul><h2 id="tree-shaking-是什么" tabindex="-1">Tree Shaking 是什么？ <a class="header-anchor" href="#tree-shaking-是什么" aria-label="Permalink to &quot;Tree Shaking 是什么？&quot;">​</a></h2><ul><li>基于 ES Module 的静态分析，打包时移除未被引用的代码</li><li>依赖 import/export 的静态性，CommonJS 无法摇树</li><li>需要注意包的 sideEffects 字段，避免误删有副作用的代码</li></ul><h2 id="babel-是什么" tabindex="-1">Babel 是什么？ <a class="header-anchor" href="#babel-是什么" aria-label="Permalink to &quot;Babel 是什么？&quot;">​</a></h2><ul><li>JavaScript 编译器，把新语法、JSX、TypeScript 转成兼容旧环境的代码</li><li>核心流程：parse 解析 -&gt; transform 转换 -&gt; generate 生成</li><li>通过插件和预设（preset-env、preset-react）扩展能力</li></ul><h2 id="eslint-是什么" tabindex="-1">ESLint 是什么？ <a class="header-anchor" href="#eslint-是什么" aria-label="Permalink to &quot;ESLint 是什么？&quot;">​</a></h2><ul><li>代码静态检查工具，发现语法错误、风格问题和潜在 bug</li><li>支持自定义规则和插件（如 eslint-plugin-react）</li><li>常配合 Prettier 一起使用，一个管规则一个管格式</li></ul><h2 id="npm、pnpm、yarn-有什么区别" tabindex="-1">npm、pnpm、yarn 有什么区别？ <a class="header-anchor" href="#npm、pnpm、yarn-有什么区别" aria-label="Permalink to &quot;npm、pnpm、yarn 有什么区别？&quot;">​</a></h2><ul><li>npm：默认包管理器，node_modules 平铺，历史问题多</li><li>yarn：解决早期 npm 安装慢、依赖版本不统一的问题，有 yarn.lock</li><li>pnpm：通过硬链接 + 内容寻址存储，节省磁盘、安装快，还能避免幽灵依赖</li></ul>',93)]))}const b=e(r,[["render",o]]);export{m as __pageData,b as default};
